Write-Host 'Step 2/4 - Adding interactive guide...';$Guide=D 'interactive-guide-v151.js';if(Test-Path $App){Copy-Item $App $Backup -Force}else{throw 'V15 index.html not found'};$html=T $App;if($html.Contains('__UPC_GUIDE151__')){Write-Host 'Guide already installed.'}else{$html=$html.Replace('</body>',("<script>`r`n$(T $Guide)`r`n</script>`r`n</body>"));$html=$html.Replace('V15 PRODUCT STUDIO','V15.1 PRODUCT STUDIO + GUIDE');[IO.File]::WriteAllText($App,$html,$U)}
