Write-Host 'Step 4/4 - Verifying guide...';try{$p=Invoke-WebRequest 'http://127.0.0.1:8765/' -UseBasicParsing -TimeoutSec 15;if(-not$p.Content.Contains('__UPC_GUIDE151__')-or-not$p.Content.Contains('? Guide')){throw 'Guide marker missing'};Write-Host 'Interactive guide PASS.' -ForegroundColor Green}catch{StopB;Copy-Item $Backup $App -Force;StartB;throw}
